#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long Integer;

typedef enum { EXPR_NUM, EXPR_VAR, EXPR_LIST } ExprType;

typedef struct Expr Expr;
struct Expr {
    ExprType type;
    Integer num;
    char *name;
    Expr **items;
    int count;
};

typedef enum { VAL_INT, VAL_FUNC } ValueType;

typedef struct Function Function;
typedef struct {
    ValueType type;
    Integer num;
    Function *func;
} Value;

typedef struct Binding Binding;
typedef struct Env Env;

struct Binding {
    char *name;
    Value value;
    Binding *next;
};

struct Env {
    Binding *head;
    Env *parent;
};

struct Function {
    char **params;
    int param_count;
    Expr **body;
    int body_count;
    Env *env;
};

static void fail(void) {
    fprintf(stderr, "Error\n");
    exit(1);
}

static void *xmalloc(size_t n) {
    void *p = malloc(n);
    if (!p) {
        fail();
    }
    return p;
}

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n);
    if (!q) {
        fail();
    }
    return q;
}

static char *xstrndup(const char *s, size_t n) {
    char *p = xmalloc(n + 1);
    memcpy(p, s, n);
    p[n] = '\0';
    return p;
}

static char *xstrdup(const char *s) {
    return xstrndup(s, strlen(s));
}

static Value make_int(Integer n) {
    Value v;
    v.type = VAL_INT;
    v.num = n;
    v.func = NULL;
    return v;
}

static Value make_func(Function *f) {
    Value v;
    v.type = VAL_FUNC;
    v.num = 0;
    v.func = f;
    return v;
}

static char *read_line(FILE *f) {
    size_t cap = 128;
    size_t len = 0;
    char *buf = xmalloc(cap);
    int c;

    while ((c = fgetc(f)) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            cap *= 2;
            buf = xrealloc(buf, cap);
        }
        buf[len++] = (char)c;
    }

    if (c == EOF && len == 0) {
        free(buf);
        return NULL;
    }

    if (len > 0 && buf[len - 1] == '\r') {
        len--;
    }
    buf[len] = '\0';
    return buf;
}

typedef struct {
    const char *s;
    size_t pos;
} Parser;

static int is_delim(int c) {
    return c == '\0' || isspace((unsigned char)c) || c == '(' || c == ')';
}

static void skip_ws(Parser *p) {
    while (isspace((unsigned char)p->s[p->pos])) {
        p->pos++;
    }
}

static Expr *new_list(void) {
    Expr *e = xmalloc(sizeof(Expr));
    e->type = EXPR_LIST;
    e->num = 0;
    e->name = NULL;
    e->items = NULL;
    e->count = 0;
    return e;
}

static void list_append(Expr *list, Expr *item) {
    size_t n = (size_t)list->count + 1;
    list->items = xrealloc(list->items, sizeof(Expr *) * n);
    list->items[list->count] = item;
    list->count++;
}

static Expr *parse_expr(Parser *p);

static Expr *parse_list(Parser *p) {
    Expr *list = new_list();

    p->pos++;
    for (;;) {
        skip_ws(p);
        if (p->s[p->pos] == ')') {
            p->pos++;
            return list;
        }
        if (p->s[p->pos] == '\0') {
            fail();
        }
        list_append(list, parse_expr(p));
    }
}

static Expr *parse_atom(Parser *p) {
    const char *s = p->s;
    size_t start = p->pos;
    unsigned char c = (unsigned char)s[start];

    if (isdigit(c) || (c == '-' && isdigit((unsigned char)s[start + 1]))) {
        char *end;
        long long n;

        errno = 0;
        n = strtoll(s + start, &end, 10);
        if (errno == ERANGE || !is_delim((unsigned char)*end)) {
            fail();
        }

        p->pos = (size_t)(end - s);

        Expr *e = xmalloc(sizeof(Expr));
        e->type = EXPR_NUM;
        e->num = (Integer)n;
        e->name = NULL;
        e->items = NULL;
        e->count = 0;
        return e;
    }

    while (!is_delim((unsigned char)s[p->pos])) {
        p->pos++;
    }
    if (p->pos == start) {
        fail();
    }

    Expr *e = xmalloc(sizeof(Expr));
    e->type = EXPR_VAR;
    e->num = 0;
    e->name = xstrndup(s + start, p->pos - start);
    e->items = NULL;
    e->count = 0;
    return e;
}

static Expr *parse_expr(Parser *p) {
    skip_ws(p);
    if (p->s[p->pos] == '(') {
        return parse_list(p);
    }
    if (p->s[p->pos] == ')') {
        fail();
    }
    return parse_atom(p);
}

static Expr *parse_line(const char *line) {
    Parser p;
    Expr *e;

    p.s = line;
    p.pos = 0;

    skip_ws(&p);
    if (p.s[p.pos] == '\0') {
        fail();
    }

    e = parse_expr(&p);
    skip_ws(&p);
    if (p.s[p.pos] != '\0') {
        fail();
    }
    return e;
}

static Env *env_new(Env *parent) {
    Env *env = xmalloc(sizeof(Env));
    env->head = NULL;
    env->parent = parent;
    return env;
}

static Binding *env_find_binding(Env *env, const char *name) {
    Env *e;
    Binding *b;

    for (e = env; e != NULL; e = e->parent) {
        for (b = e->head; b != NULL; b = b->next) {
            if (strcmp(b->name, name) == 0) {
                return b;
            }
        }
    }
    return NULL;
}

static void env_add_binding(Env *env, const char *name, Value value) {
    Binding *b = xmalloc(sizeof(Binding));
    b->name = xstrdup(name);
    b->value = value;
    b->next = env->head;
    env->head = b;
}

static Value env_lookup(Env *env, const char *name) {
    Binding *b = env_find_binding(env, name);
    if (!b) {
        fail();
    }
    return b->value;
}

static void env_define(Env *env, const char *name, Value value) {
    Binding *b = env_find_binding(env, name);
    if (b) {
        b->value = value;
    } else {
        env_add_binding(env, name, value);
    }
}

static Value eval(Env *env, Expr *expr);
static Value eval_application(Env *env, Expr *expr);
static Integer eval_integer(Env *env, Expr *expr);

static Integer eval_integer(Env *env, Expr *expr) {
    Value v = eval(env, expr);
    if (v.type != VAL_INT) {
        fail();
    }
    return v.num;
}

static int is_symbol(Expr *expr, const char *name) {
    return expr->type == EXPR_VAR && strcmp(expr->name, name) == 0;
}

static Value eval_add(Expr *list, Env *env) {
    Integer acc = 0;
    int i;

    for (i = 1; i < list->count; i++) {
        acc += eval_integer(env, list->items[i]);
    }
    return make_int(acc);
}

static Value eval_sub(Expr *list, Env *env) {
    Integer acc;
    int i;

    if (list->count < 2) {
        fail();
    }

    acc = eval_integer(env, list->items[1]);
    if (list->count == 2) {
        return make_int(-acc);
    }

    for (i = 2; i < list->count; i++) {
        acc -= eval_integer(env, list->items[i]);
    }
    return make_int(acc);
}

static Value eval_mul(Expr *list, Env *env) {
    Integer acc = 1;
    int i;

    for (i = 1; i < list->count; i++) {
        acc *= eval_integer(env, list->items[i]);
    }
    return make_int(acc);
}

static Value eval_div(Expr *list, Env *env) {
    Integer acc;
    int i;

    if (list->count < 2) {
        fail();
    }

    acc = eval_integer(env, list->items[1]);
    if (list->count == 2) {
        if (acc == 0) {
            fail();
        }
        return make_int(1 / acc);
    }

    for (i = 2; i < list->count; i++) {
        Integer d = eval_integer(env, list->items[i]);
        if (d == 0) {
            fail();
        }
        acc /= d;
    }
    return make_int(acc);
}

static Value eval_cmp(Expr *list, Env *env, const char *op) {
    Integer a;
    Integer b;
    int result = 0;

    if (list->count != 3) {
        fail();
    }

    a = eval_integer(env, list->items[1]);
    b = eval_integer(env, list->items[2]);

    if (strcmp(op, "=") == 0) {
        result = (a == b);
    } else if (strcmp(op, "<") == 0) {
        result = (a < b);
    } else if (strcmp(op, ">") == 0) {
        result = (a > b);
    } else {
        fail();
    }

    return make_int(result ? 1 : 0);
}

static Value eval_if(Expr *list, Env *env) {
    if (list->count != 4) {
        fail();
    }

    if (eval_integer(env, list->items[1]) != 0) {
        return eval(env, list->items[2]);
    }
    return eval(env, list->items[3]);
}

static Value eval_cond(Expr *list, Env *env) {
    int i;

    for (i = 1; i < list->count; i++) {
        Expr *clause = list->items[i];
        Expr *test;

        if (clause->type != EXPR_LIST || clause->count != 2) {
            fail();
        }

        test = clause->items[0];
        if (is_symbol(test, "else")) {
            return eval(env, clause->items[1]);
        }
        if (eval_integer(env, test) != 0) {
            return eval(env, clause->items[1]);
        }
    }

    fail();
    return make_int(0);
}

static Value eval_begin(Expr *list, Env *env) {
    Value result;
    int i;

    if (list->count < 2) {
        fail();
    }

    result = make_int(0);
    for (i = 1; i < list->count; i++) {
        result = eval(env, list->items[i]);
    }
    return result;
}

static Function *make_function(Env *env, Expr *params, int start,
                               Expr **body, int body_count) {
    Function *f;
    int pcount;
    int i;

    if (params->type != EXPR_LIST || body_count < 1) {
        fail();
    }

    pcount = params->count - start;
    if (pcount < 0) {
        fail();
    }

    f = xmalloc(sizeof(Function));
    f->param_count = pcount;
    f->params = pcount ? xmalloc(sizeof(char *) * (size_t)pcount) : NULL;
    for (i = 0; i < pcount; i++) {
        Expr *param = params->items[start + i];
        if (param->type != EXPR_VAR) {
            fail();
        }
        f->params[i] = param->name;
    }

    f->body = body;
    f->body_count = body_count;
    f->env = env;
    return f;
}

static Value eval_define(Env *env, Expr *list) {
    Expr *target;

    if (list->count < 3) {
        fail();
    }

    target = list->items[1];

    if (target->type == EXPR_VAR) {
        Value value;

        if (list->count != 3) {
            fail();
        }
        value = eval(env, list->items[2]);
        env_define(env, target->name, value);
        return value;
    }

    if (target->type != EXPR_LIST || target->count < 1 ||
        target->items[0]->type != EXPR_VAR) {
        fail();
    }

    Function *f = make_function(env, target, 1, list->items + 2,
                                list->count - 2);
    Value value = make_func(f);
    env_define(env, target->items[0]->name, value);
    return value;
}

static Value eval_lambda(Env *env, Expr *list) {
    Expr *params;

    if (list->count < 3) {
        fail();
    }

    params = list->items[1];
    if (params->type != EXPR_LIST) {
        fail();
    }

    Function *f = make_function(env, params, 0, list->items + 2,
                                list->count - 2);
    return make_func(f);
}

static Value eval_let(Env *env, Expr *list) {
    Expr *bindings;
    Value *vals;
    Env *local;
    Value result;
    int n;
    int i;

    if (list->count < 3) {
        fail();
    }

    bindings = list->items[1];
    if (bindings->type != EXPR_LIST) {
        fail();
    }

    n = bindings->count;
    vals = n ? xmalloc(sizeof(Value) * (size_t)n) : NULL;

    for (i = 0; i < n; i++) {
        Expr *binding = bindings->items[i];

        if (binding->type != EXPR_LIST || binding->count != 2 ||
            binding->items[0]->type != EXPR_VAR) {
            fail();
        }
        vals[i] = eval(env, binding->items[1]);
    }

    local = env_new(env);
    for (i = 0; i < n; i++) {
        Expr *binding = bindings->items[i];
        env_add_binding(local, binding->items[0]->name, vals[i]);
    }

    result = make_int(0);
    for (i = 2; i < list->count; i++) {
        result = eval(local, list->items[i]);
    }

    free(vals);
    return result;
}

static Value eval_application(Env *env, Expr *expr) {
    Value fv;
    Value *args;
    Value result;
    Env *call_env;
    int argc;
    int i;

    if (expr->count < 1) {
        fail();
    }

    fv = eval(env, expr->items[0]);
    if (fv.type != VAL_FUNC) {
        fail();
    }

    argc = expr->count - 1;
    if (argc != fv.func->param_count) {
        fail();
    }

    args = argc ? xmalloc(sizeof(Value) * (size_t)argc) : NULL;
    for (i = 0; i < argc; i++) {
        args[i] = eval(env, expr->items[i + 1]);
    }

    call_env = env_new(fv.func->env);
    for (i = 0; i < argc; i++) {
        env_add_binding(call_env, fv.func->params[i], args[i]);
    }

    result = make_int(0);
    for (i = 0; i < fv.func->body_count; i++) {
        result = eval(call_env, fv.func->body[i]);
    }

    free(args);
    return result;
}

static Value eval(Env *env, Expr *expr) {
    Expr *head;
    const char *name;

    if (expr->type == EXPR_NUM) {
        return make_int(expr->num);
    }
    if (expr->type == EXPR_VAR) {
        return env_lookup(env, expr->name);
    }

    if (expr->count < 1) {
        fail();
    }

    head = expr->items[0];
    if (head->type == EXPR_VAR) {
        name = head->name;
        if (strcmp(name, "+") == 0) {
            return eval_add(expr, env);
        }
        if (strcmp(name, "-") == 0) {
            return eval_sub(expr, env);
        }
        if (strcmp(name, "*") == 0) {
            return eval_mul(expr, env);
        }
        if (strcmp(name, "/") == 0) {
            return eval_div(expr, env);
        }
        if (strcmp(name, "=") == 0 || strcmp(name, "<") == 0 ||
            strcmp(name, ">") == 0) {
            return eval_cmp(expr, env, name);
        }
        if (strcmp(name, "if") == 0) {
            return eval_if(expr, env);
        }
        if (strcmp(name, "cond") == 0) {
            return eval_cond(expr, env);
        }
        if (strcmp(name, "define") == 0) {
            return eval_define(env, expr);
        }
        if (strcmp(name, "lambda") == 0) {
            return eval_lambda(env, expr);
        }
        if (strcmp(name, "let") == 0) {
            return eval_let(env, expr);
        }
        if (strcmp(name, "begin") == 0) {
            return eval_begin(expr, env);
        }
    }

    return eval_application(env, expr);
}

int main(void) {
    Env *global = env_new(NULL);
    char *line;

    while ((line = read_line(stdin)) != NULL) {
        Expr *expr = parse_line(line);
        Value value = eval(global, expr);

        if (value.type == VAL_FUNC) {
            printf("0\n");
        } else {
            printf("%lld\n", value.num);
        }

        free(line);
    }

    return 0;
}
